package com.mediassistrover.backend.service.impl;
import com.mediassistrover.backend.dto.common.DeletionContracts.*;import com.mediassistrover.backend.exception.*;import lombok.RequiredArgsConstructor;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.nio.ByteBuffer;import java.util.*;import java.util.UUID;
@Service @RequiredArgsConstructor public class ScheduleHardDeleteService {private final JdbcTemplate jdbc;
 @Transactional(readOnly=true) public DeletionImpactResponse impact(UUID id){byte[] k=key(id);exists(k,id);Map<String,Long> refs=refs(k);List<String>b=refs.entrySet().stream().filter(e->e.getValue()>0).map(e->e.getKey()+" has "+e.getValue()+" reference(s)").toList();return new DeletionImpactResponse(id,"Schedule",b.isEmpty(),b,Map.copyOf(refs));}
 @Transactional(propagation=Propagation.MANDATORY) public HardDeleteResponse delete(UUID id){byte[]k=key(id);if(jdbc.query("SELECT schedule_id FROM Schedule WHERE schedule_id=? FOR UPDATE",(r,n)->r.getBytes(1),k).isEmpty())throw new ResourceNotFoundException("Schedule not found: "+id);var i=impact(id);if(!i.canHardDelete())throw new ConflictException(String.join(", ",i.blockers()));return new HardDeleteResponse(id,"Schedule",Map.of("Schedule",(long)jdbc.update("DELETE FROM Schedule WHERE schedule_id=?",k)));}
 private Map<String,Long> refs(byte[]k){var o=new LinkedHashMap<String,Long>();var rs=jdbc.query("SELECT TABLE_NAME,COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE REFERENCED_TABLE_SCHEMA=DATABASE() AND REFERENCED_TABLE_NAME='Schedule' ORDER BY TABLE_NAME,COLUMN_NAME",(r,n)->List.of(r.getString(1),r.getString(2)));for(var x:rs){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM `"+x.get(0)+"` WHERE `"+x.get(1)+"`=?",Long.class,k);o.put(x.get(0)+"."+x.get(1),n==null?0:n);}return o;} private void exists(byte[]k,UUID id){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM Schedule WHERE schedule_id=?",Long.class,k);if(n==null||n==0)throw new ResourceNotFoundException("Schedule not found: "+id);}private static byte[]key(UUID id){return ByteBuffer.allocate(16).putLong(id.getMostSignificantBits()).putLong(id.getLeastSignificantBits()).array();}}
